/*
B"H
Awtsmoos Stylesheet
*/

:root {
    /* Palette */
    --bg-void: #050507;
    --bg-card: #0e0e11;
    --bg-card-header: rgba(20, 20, 25, 0.6);
    --bg-input: #020203;
    
    --border-dim: #1f1f23;
    --border-highlight: #3f3f46;
    
    --text-main: #e4e4e7;
    --text-muted: #a1a1aa;
    --text-dim: #52525b;
    
    --accent-primary: #06b6d4; /* Cyan 500 */
    --accent-glow: #22d3ee;    /* Cyan 400 */
    --accent-dim: #0e7490;
    
    --blue-deep: #2563eb;
    --blue-vivid: #3b82f6;

    --success: #4ade80;
    --error: #ef4444;

    /* Spacing */
    --radius-lg: 12px;
    --radius-md: 8px;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: 'JetBrains Mono', monospace;
    background-color: var(--bg-void);
    color: var(--text-main);
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 1rem;
    
    /* Subtle ambient background */
    background-image: 
        radial-gradient(circle at 50% 0%, rgba(6, 182, 212, 0.05) 0%, transparent 50%),
        radial-gradient(circle at 100% 100%, rgba(37, 99, 235, 0.05) 0%, transparent 50%);
}

/* --- Holy Headers (B"H) --- */
.bh-corner-left {
    position: fixed;
    top: 1rem;
    left: 1.5rem;
    font-size: 2.5rem;
    font-weight: 700;
    color: var(--accent-glow);
    text-shadow: 0 0 20px rgba(6, 182, 212, 0.4);
    z-index: 9999;
    pointer-events: none;
    font-family: 'JetBrains Mono', monospace;
    opacity: 0.8;
}

.bh-corner-right {
    position: fixed;
    top: 0.8rem;
    right: 1.5rem;
    font-size: 3rem;
    font-weight: 700;
    color: var(--accent-glow);
    text-shadow: 0 0 20px rgba(6, 182, 212, 0.4);
    z-index: 9999;
    pointer-events: none;
    font-family: 'Times New Roman', serif; /* Serif for authentic Hebrew look */
    opacity: 0.8;
}

/* --- Card Component --- */

.compiler-card {
    width: 100%;
    max-width: 42rem; /* approx 672px */
    background-color: var(--bg-card);
    border: 1px solid var(--border-dim);
    border-radius: var(--radius-lg);
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
    overflow: hidden;
    position: relative;
    backdrop-filter: blur(10px);
}

.compiler-card::before {
    /* Top border glow hint */
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--border-highlight), transparent);
    opacity: 0.5;
}

/* --- Header --- */

.card-header {
    background-color: var(--bg-card-header);
    padding: 1.5rem;
    border-bottom: 1px solid var(--border-dim);
}

.app-title {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--accent-glow);
    margin-bottom: 0.5rem;
    letter-spacing: -0.02em;
    text-shadow: 0 0 20px rgba(6, 182, 212, 0.3);
}

.app-subtitle {
    font-size: 0.875rem;
    color: var(--text-muted);
    line-height: 1.5;
}

/* --- Content Area --- */

.card-content {
    padding: 2rem;
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

/* Input */
.input-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.input-label {
    font-size: 0.875rem;
    font-weight: 500;
    color: var(--text-main);
}

.input-field {
    width: 100%;
    background-color: var(--bg-input)

